import{_ as t,o,c as d,a2 as a}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Deploying","description":"","frontmatter":{},"headers":[],"relativePath":"developers/deploying.md","filePath":"developers/deploying.md"}'),s={name:"developers/deploying.md"};function c(i,e,r,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="deploying" tabindex="-1">Deploying <a class="header-anchor" href="#deploying" aria-label="Permalink to &quot;Deploying&quot;">​</a></h1><p>Suho deploys in three parts. The static landing and docs and the app static bundle go to Cloudflare Pages. The guardian goes to a Node host on Railway. The app is a static bundle that points at the deployed guardian over REST.</p><p>Everything cross-origin is env-configurable, so nothing is hardcoded to one domain.</p><h2 id="what-deploys-where" tabindex="-1">What deploys where <a class="header-anchor" href="#what-deploys-where" aria-label="Permalink to &quot;What deploys where&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Host</th><th>Live at</th></tr></thead><tbody><tr><td>Landing + docs (<code>site/</code>)</td><td>Cloudflare Pages (static)</td><td><code>https://suhowallet.com</code></td></tr><tr><td>App (<code>app/</code>)</td><td>Cloudflare Pages (static)</td><td><code>https://app.suhowallet.com</code></td></tr><tr><td>Guardian (<code>guardian/</code>)</td><td>Railway (Node)</td><td><code>https://api.suhowallet.com</code></td></tr></tbody></table><p>Order matters: deploy the guardian first and confirm <code>https://api.suhowallet.com/health</code> responds, then build the app (its guardian URL is baked in at build time), then the landing and docs.</p><h2 id="landing-docs-cloudflare-pages-static" tabindex="-1">Landing + docs (Cloudflare Pages, static) <a class="header-anchor" href="#landing-docs-cloudflare-pages-static" aria-label="Permalink to &quot;Landing + docs (Cloudflare Pages, static)&quot;">​</a></h2><p>The landing is static in <code>site/</code>. The docs build into <code>site/docs</code>, so both serve from one folder and one deploy.</p><ul><li><strong>Build command:</strong> <code>cd docs &amp;&amp; npm ci &amp;&amp; npm run docs:build &amp;&amp; cd ../site &amp;&amp; node inject-config.mjs</code></li><li><strong>Build output directory:</strong> <code>site</code></li><li><strong>Env:</strong> <code>SUHO_APP_URL=https://app.suhowallet.com</code> (read by both the docs &quot;Launch app&quot; link and the landing&#39;s Launch-app CTA), <code>NODE_VERSION=20</code>.</li></ul><p><code>docs:build</code> compiles VitePress into <code>../site/docs</code> (base <code>/docs/</code>), then <code>inject-config.mjs</code> rewrites the landing&#39;s Launch-app URL from the localhost dev default to <code>SUHO_APP_URL</code>. <code>cleanUrls: false</code> keeps the explicit <code>.html</code> links working on a plain static host, so <code>/</code> serves the landing and <code>/docs/*.html</code> serves the docs with no rewrite rules.</p><h2 id="app-cloudflare-pages-static-bundle" tabindex="-1">App (Cloudflare Pages, static bundle) <a class="header-anchor" href="#app-cloudflare-pages-static-bundle" aria-label="Permalink to &quot;App (Cloudflare Pages, static bundle)&quot;">​</a></h2><p>The app reads these build-time variables. Point them at production:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Value</th><th>Dev default</th></tr></thead><tbody><tr><td><code>VITE_GUARDIAN_URL</code></td><td><code>https://api.suhowallet.com</code></td><td><code>http://localhost:8787</code></td></tr><tr><td><code>VITE_RP_ID</code></td><td><code>suhowallet.com</code></td><td><code>localhost</code></td></tr><tr><td><code>VITE_APP_URL</code></td><td><code>https://app.suhowallet.com</code></td><td>current origin</td></tr><tr><td><code>VITE_LANDING_URL</code></td><td><code>https://suhowallet.com/</code></td><td><code>http://localhost:8899/</code></td></tr><tr><td><code>VITE_DOCS_URL</code></td><td><code>https://suhowallet.com/docs/overview/what-is-suho.html</code></td><td>localhost docs</td></tr></tbody></table><ul><li><strong>Build command:</strong> <code>cd app &amp;&amp; npm ci &amp;&amp; npm run build</code></li><li><strong>Build output directory:</strong> <code>app/dist</code></li><li><code>VITE_RP_ID</code> is the WebAuthn Relying Party ID passkeys bind to. It must be the app&#39;s registrable domain, so a passkey created on <code>app.suhowallet.com</code> sets <code>suhowallet.com</code>. A mismatch makes every passkey create and sign fail. <code>VITE_APP_URL</code> is used to build the card QR link to the shareable <code>/verify</code> view.</li></ul><p>The output in <code>app/dist</code> is a static bundle. It talks to the guardian over REST, so the guardian must be up and must allow the app&#39;s origin (see CORS below). <code>VITE_*</code> values are baked at build time, so changing one needs a rebuild, not just an env change.</p><h2 id="guardian-railway-node" tabindex="-1">Guardian (Railway, Node) <a class="header-anchor" href="#guardian-railway-node" aria-label="Permalink to &quot;Guardian (Railway, Node)&quot;">​</a></h2><p>Railway root directory is <code>guardian</code>; build is <code>npm install</code>; start is <code>npm start</code> (it runs TypeScript directly through <code>tsx</code>, no compile step). Attach the Postgres service so <code>DATABASE_URL</code> is injected, and leave <code>DATABASE_PUBLIC_URL</code> unset so the internal host is used.</p><p>The guardian reads these from the environment. Keys come from <code>.env</code> locally, from host variables in production. Never commit <code>.env</code>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>Listen port. Railway injects it; falls back to 8787 locally.</td></tr><tr><td><code>SUHO_CORS_ORIGINS</code></td><td>Origin allowlist, set to <code>https://app.suhowallet.com</code>. Unset means open (<code>*</code>), the dev default.</td></tr><tr><td><code>DATABASE_URL</code></td><td>Postgres connection. Injected by attaching the Railway Postgres service (internal host).</td></tr><tr><td><code>DEPLOYER_PRIVATE_KEY</code></td><td>Relayer key (pays gas) and SuhoCodeAttester issuer (mints recovery codes). Testnet only.</td></tr><tr><td><code>ALICE_PRIVATE_KEY</code></td><td>Legacy demo EOA key, held only for the one-time 7702 upgrade. Testnet only.</td></tr><tr><td><code>RESEND_API_KEY</code></td><td>Sends recovery and confirmation email through Resend.</td></tr><tr><td><code>SUHO_EMAIL_ENC_KEY</code></td><td>Encrypts recovery emails at rest. Must stay constant, or stored emails become undecryptable.</td></tr><tr><td><code>SUHO_EMAIL_FROM</code></td><td>Sender, e.g. <code>Suho &lt;no-reply@suhowallet.com&gt;</code> (a Resend-verified domain).</td></tr><tr><td><code>SUHO_OPS_TOKEN</code></td><td>Bearer token for the <code>/ops</code> monitoring endpoint.</td></tr><tr><td><code>SUHO_RELAYER_FLOOR_WEI</code></td><td>Below this relayer balance, sponsored onboarding pauses; reimbursed ops continue. <code>0</code> or unset disables it.</td></tr><tr><td><code>SUHO_ONBOARD_DAILY_CAP</code></td><td>Max sponsored onboardings per UTC day (default 200).</td></tr></tbody></table><p><code>GET /health</code> reports the live relayer balance, floor state, onboarding counts, relays served, and chain head with no secrets. See <a href="/docs/developers/costs.html">Costs and limits</a> for the reimbursement model and the sponsored-onboarding caps.</p><p>Set <code>SUHO_CORS_ORIGINS</code> to the app&#39;s real origin in production. Only listed origins are echoed back; every other origin is refused at the browser. Leaving it open is a dev convenience, not a production setting. On boot the guardian logs its port, the active CORS mode, and whether the database schema is ready, so a misconfiguration is visible in the first lines of output.</p><h2 id="never-commit-keys" tabindex="-1">Never commit keys <a class="header-anchor" href="#never-commit-keys" aria-label="Permalink to &quot;Never commit keys&quot;">​</a></h2><p><code>.env</code> stays out of the repo. In production, keys live as host variables (Railway) and nowhere else. The request-body guard already rejects anything key-shaped sent to any endpoint, but the deploy discipline is the same: keys are configuration, not code.</p>',23)])])}const m=t(s,[["render",c]]);export{u as __pageData,m as default};
